set -euo pipefail
case $(hostname -s) in ocne-op|ocne-cp|ocne-w1|ocne-w2) ;; *) exit 1;; esac
[[ $(id -u labadmin) == 1001 ]]
install -d -m 0700 -o labadmin -g labadmin /home/labadmin/.ssh
auth=/home/labadmin/.ssh/authorized_keys
touch "$auth"
while IFS= read -r key; do grep -qxF "$key" "$auth" || printf '%s\n' "$key" >> "$auth"; done <<'PUBLIC_KEYS'
ssh-rsa  labadmin@ocne-op.lab.test
ssh-rsa  labadmin@ocne-cp.lab.test
ssh-rsa  labadmin@ocne-w1.lab.test
ssh-rsa  labadmin@ocne-w2.lab.test
ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIFHoKtVfkF2vKeumykF4/pTMs8cccer/fZg9qCpdcSid workstation@ocne19-lab
PUBLIC_KEYS
chown labadmin:labadmin "$auth"
chmod 0600 "$auth"
restorecon -RF /home/labadmin/.ssh
ssh-keygen -lf "$auth"